    for (int v : A) {
        xorAll ^= v;
    }
    int magicIndex = 0;
    for (int i = 0; i < 32; i++) {
        if ((xorAll & (1 << i)) == (1 << i)) {
            magicIndex = i;
            break;
        }
    }
    int num1 = 0;
    int num2 = 0;
    for (int v : A) {
        if ((v & (1 << magicIndex)) == (1 << magicIndex)) {
            num1 ^= v;
