public int[] solve(int[] A) {
    int N = A.length;
    int xorRange = 0;
    for (int i = 1; i <= N + 2; i++) {
        xorRange ^= i;
    }
    int xorArr = 0;
    for (int i = 0; i < N; i++) {
        xorArr ^= A[i];
    }
    int X = xorRange ^ xorArr;
    int p = 0;
    for (int i = 0; i < 32; i++) {
        if ((X & (1 << i)) == (1 << i)) {
            p = i;
            break;
        }
    }
    int allSet = 0;
    for (int i = 1; i <= N + 2; i++) {
        if ((i & (1 << p)) == (1 << p)) {
            allSet ^= i;
        }
    }
    int arrSet = 0;
    for (int i = 0; i < N; i++) {
        if ((A[i] & (1 << p)) == (1 << p)) {
            arrSet ^= A[i];
        }
    }
    int allUnset = allSet ^ xorRange;
    int arrUnset = arrSet ^ xorArr;
    int num1 = arrSet ^ allSet;
    int num2 = arrUnset ^ allUnset;
    int[] B = new int[2];
    B[0] = Math.min(num1, num2);
    B[1] = Math.max(num1, num2);
    return B;
}

public int findMinXor(int[] A) {
    Arrays.sort(A);
    int minXor = A[0] ^ A[1];
    int start = 1;
    int end = 2;
    int n = A.length;
    while (end < n) {
        int currentXor = A[start] ^ A[end];
        if (currentXor < minXor) {
            minXor = currentXor;
            if (minXor == 0) {
                break;
            }
        }
        start++;
        end++;
    }
    return minXor;
}

public int solve(int A) {
    int X = A;

    int numberOfBits = numberOfBits(A);
    int Y = 1 << numberOfBits;

    for (int i = 0; i < numberOfBits; i++) {
        if (checkIfIthBitIsSet(A, i)) {
            X = unSetIthBit(X, i);
        } else {
            X = setIthBit(X, i);
        }
    }

    return X ^ Y;
}

private boolean checkIfIthBitIsSet(int num, int pos) {
    return (num & (1 << pos)) == 1 << pos;
}

private int setIthBit(int num, int pos) {
    return num | (1 << pos);
}

private int unSetIthBit(int num, int pos) {
    return num & ~(1 << pos);
}

private int numberOfBits(int num) {
    return (int) ((Math.log(num) / Math.log(2)) + 1);
}
